CREATE TABLE Coach (
    Age INTEGER,
    Coach_ID INTEGER PRIMARY KEY,
    Name VARCHAR(255)
);

CREATE TABLE Player (
    Height FLOAT,
    Name VARCHAR(255),
    Player_ID INTEGER PRIMARY KEY,
    Weight FLOAT
);

CREATE TABLE Team (
    Establishment_Date DATETIME,
    Representative_Region VARCHAR(255),
    Team_ID INTEGER PRIMARY KEY,
    Team_Name VARCHAR(255)
);

CREATE TABLE Coach_Team (
    Coach_ID INTEGER NOT NULL,
    Coaching_Start_Date DATETIME,
    Team_ID INTEGER NOT NULL,
    PRIMARY KEY (Coach_ID, Team_ID, Coaching_Start_Date),
    FOREIGN KEY (Coach_ID) REFERENCES Coach(Coach_ID),
    FOREIGN KEY (Team_ID) REFERENCES Team(Team_ID)
);

CREATE TABLE Player_Team (
    Joining_Date DATETIME,
    Player_ID INTEGER NOT NULL,
    Team_ID INTEGER NOT NULL,
    PRIMARY KEY (Player_ID, Team_ID, Joining_Date),
    FOREIGN KEY (Player_ID) REFERENCES Player(Player_ID),
    FOREIGN KEY (Team_ID) REFERENCES Team(Team_ID)
);
